// TrailEnvelope carries the pass-through backbone columns — every plain
// column that is not the Key, Order or state-view Lifecycle role. Pass
// one to Begin; it is written verbatim onto the row and read back onto
// the entity.
type TrailEnvelope struct {
	NaturalKey []byte
	ExpiresAt  time.Time
}

