// TrailStore is single-goroutine, like every part it composes. Batched
// cached retrieval is not built in — attach a TrailCache view.
type TrailStore struct {
	exec     recordstore.ExecutorI
	alloc    memory.Allocator
	cfg      TrailStoreConfig
	dml      *lowlevel.InEntityFactsTable
	buffered int
	// pending holds transferred-but-uninserted records after a failed
	// Flush; the next Flush ships them (DiscardPending drops them).
	pending []arrow.RecordBatch
	// dirty tracks locally-written keys between Commit/Delete and the
	// next successful Flush (or DiscardPending). Attached cache views
	// pin these keys until the flush lands (eviction cannot expose the
	// pre-write row) and their fetchers refuse to cache them — the
	// remaining guard for writes the views could not materialize (Raw
	// commits) and for InvalidateAll inside a dirty window.
	dirty map[uint64]struct{}
	// onWrite/onFlush hold the write-through hooks of attached cache
	// views (NewTrailCache registers one pair per view): onWrite populates
	// and pins the committed entity (nil = not materializable or a
	// discarded write — invalidate instead); onFlush releases the pin
	// once the row is durable.
	onWrite []func(uint64, *TrailEntity)
	onFlush []func(uint64)
	// stampers is cfg.Stampers, consulted per Begin (ADR-0112 M1).
	stampers []recordstore.ReferenceStamper
	// written holds the rows the write observer was told were committed and
	// has not yet been told are durable or discarded (ADR-0295 §SD7); empty
	// without an observer.
	written []recordstore.WrittenKey[uint64, time.Time]
}

// NewTrailStore wires the store. A nil alloc selects the Go allocator.
func NewTrailStore(exec recordstore.ExecutorI, alloc memory.Allocator, cfg TrailStoreConfig) (inst *TrailStore) {
	if cfg.Table != "" {
		if terr := recordstore.CheckTableRef(cfg.Table); terr != nil {
			panic("TrailStore: " + terr.Error())
		}
	}
	if cfg.ReadTable != "" {
		if terr := recordstore.CheckTableRef(cfg.ReadTable); terr != nil {
			panic("TrailStore: ReadTable: " + terr.Error())
		}
	}
	if alloc == nil {
		alloc = memory.NewGoAllocator()
	}
	inst = &TrailStore{exec: exec, alloc: alloc, cfg: cfg, dml: lowlevel.NewInEntityFactsTable(alloc, 64), dirty: make(map[uint64]struct{}), stampers: cfg.Stampers}
	return
}

// writeTable is the table reference DDL and INSERT use: the configured
// override when set, else the baked TrailTableName.
func (inst *TrailStore) writeTable() string {
	if inst.cfg.Table != "" {
		return inst.cfg.Table
	}
	return TrailTableName
}

// readTable is the table reference SELECT and DESCRIBE use: ReadTable
// when set, else the table written to (ADR-0296 §SD8).
func (inst *TrailStore) readTable() string {
	if inst.cfg.ReadTable != "" {
		return inst.cfg.ReadTable
	}
	return inst.writeTable()
}

// applyStampers consults the configured stampers and pushes their surrogate
// ids as ambient HighCardRef memberships onto the open entity (ADR-0112 M1),
// returning the count so Commit/Rollback pop exactly that many. ctx is
// BeginCtx's — the call identity a stamper interns rides on it (ADR-0295
// §SD7). No stampers means no pushes: inert.
func (inst *TrailStore) applyStampers(ctx context.Context) (pushed int) {
	for _, s := range inst.stampers {
		for id, err := range s.Current(ctx) {
			if err != nil {
				inst.dml.AppendError(err)
				continue
			}
			inst.dml.PushMembershipHighCardRef(uint64(id))
			pushed++
		}
	}
	return
}

// notifyWrite fires the write-through hooks of attached cache views:
// ent is the just-committed entity (the views populate and pin it),
// or nil when the row is not faithfully materializable (Raw commits)
// or a buffered write is being discarded — the views then invalidate
// the key instead.
func (inst *TrailStore) notifyWrite(key uint64, ent *TrailEntity) {
	for _, f := range inst.onWrite {
		f(key, ent)
	}
}

// notifyFlush releases the attached views' dirty-window pins after a
// successful Flush made the key durable.
func (inst *TrailStore) notifyFlush(key uint64) {
	for _, f := range inst.onFlush {
		f(key)
	}
}

// noteCommitted tells the write observer about a buffered row and keeps
// it until the observer is told its fate (ADR-0295 §SD7).
func (inst *TrailStore) noteCommitted(w recordstore.WrittenKey[uint64, time.Time]) {
	if inst.cfg.WriteObserver == nil {
		return
	}
	inst.written = append(inst.written, w)
	inst.cfg.WriteObserver.Committed(w)
}

// takeWritten detaches the rows noteCommitted kept and ranges over them.
// Detaching before the observer runs means a row it commits from its
// callback lands in a fresh buffer, reported with a later flush, and a
// panicking observer cannot have the same rows reported twice.
func (inst *TrailStore) takeWritten() iter.Seq[recordstore.WrittenKey[uint64, time.Time]] {
	written := inst.written
	inst.written = nil
	return func(yield func(recordstore.WrittenKey[uint64, time.Time]) bool) {
		for _, w := range written {
			if !yield(w) {
				return
			}
		}
	}
}

// VerifySchema compares the live table's columns — names and order —
// against the generated schema. This store cannot create or repair
// its table (generated ExternallyProvisioned), so nothing here
// constrains the live shape, and the decode is positional: drift
// fails late or, for same-typed column swaps, silently. Run
// VerifySchema at startup, before the first read;
// facts_ddl_clickhouse.out.sql states the shape it expects.
//
// It checks the COLUMN contract only. The membership-id contract is not
// checked and cannot be from the schema alone: the ids live in the
// membership columns as ordinary values, and a FAT table legitimately
// carries other kinds' ids beside this store's. Rows written under a
// different id assignment therefore pass VerifySchema and then match
// nothing — every component decodes absent, with no error. Compare
// TrailMembershipIds against the writer's assignment when pointing this
// store at rows it did not write.
//
// What it describes is the reader's own projection — DESCRIBE over
// `SELECT *`, not over the table — because that is what the positional
// decode consumes. DESCRIBE TABLE lists columns SELECT * does not return
// (MATERIALIZED, ALIAS, EPHEMERAL), so a table legitimately carrying one
// beside the generated shape — a derived column added by ALTER after
// EnsureTable, which is how a store gets a skip index over a value its
// leeway attributes only encode — would fail a check whose contract still
// held. Describing the projection also follows the asterisk_include_*
// settings, which decide what SELECT * returns and which nothing here
// pins: under those, a derived column IS in the decode, and this notices
// where a column-kind filter would have blessed the mis-decode.
func (inst *TrailStore) VerifySchema(ctx context.Context) (err error) {
	live := make([]string, 0, 64)
	for rec, rerr := range inst.exec.QueryArrow(ctx, "DESCRIBE (SELECT * FROM "+inst.readTable()+")"+factsArrowOutputSettings) {
		if rerr != nil {
			err = eh.Errorf("describe table %s: %w", inst.readTable(), rerr)
			return
		}
		names, ok := rec.Column(0).(*array.String)
		if !ok {
			err = eh.Errorf("describe table %s: name column is %s, not a string", inst.readTable(), rec.Column(0).DataType())
			rec.Release()
			return
		}
		for i := range int(rec.NumRows()) {
			live = append(live, names.Value(i))
		}
		rec.Release()
	}
	want := lowlevel.CreateSchemaFactsTable().Fields()
	if len(live) != len(want) {
		err = eh.Errorf("schema drift on %s: table has %d columns, the generated schema expects %d — regenerated code against an old table (or vice versa); migrate or regenerate", inst.readTable(), len(live), len(want))
		return
	}
	for i, f := range want {
		if live[i] != f.Name {
			err = eh.Errorf("schema drift on %s: column %d is %q, the generated schema expects %q — the decode is positional; migrate or regenerate", inst.readTable(), i, live[i], f.Name)
			return
		}
	}
	return
}

// OpenTrailStore is NewTrailStore plus the startup check: it runs VerifySchema and
// returns a store ready to Begin. This store cannot create its table
// (generated ExternallyProvisioned), so a missing table fails here.
//
// On failure the store is closed and nil is returned. It takes an
// executor, not a client — which executor reaches the server is the
// caller's layer (ADR-0105 D1). NewTrailStore panics on a malformed config
// and so does this. A caller that cannot afford the DESCRIBE at startup
// keeps using NewTrailStore.
func OpenTrailStore(ctx context.Context, exec recordstore.ExecutorI, alloc memory.Allocator, cfg TrailStoreConfig) (inst *TrailStore, err error) {
	st := NewTrailStore(exec, alloc, cfg)
	err = st.VerifySchema(ctx)
	if err != nil {
		st.Close()
		err = eh.Errorf("open trailStore: %w", err)
		return
	}
	inst = st
	return
}

// TrailEntityBuilder assembles one entity: envelope from Begin, components
// via Add*, direct attribute manipulation via Raw, then Commit.
type TrailEntityBuilder struct {
	store *TrailStore
	key   uint64
	// ent mirrors the typed Add* calls so Commit can write the entity
	// through to attached cache views; raw marks commits that touched
	// the DML directly — those cannot be materialized faithfully and
	// invalidate the key instead.
	ent TrailEntity
	raw bool
	// buf holds each component's section contributions until Commit, so
	// components sharing a section share its frame. It also holds the
	// frame invariants: one contribution per kind, and typed Adds
	// exclusive with Raw (ADR-0183 D4).
	buf dmlruntime.DeferredSectionBuffer
	// pushed counts the ambient memberships Begin pushed via the stampers;
	// Commit/Rollback pop exactly that many (ADR-0112 M1).
	pushed int
	// ident is BeginCtx's call identity: who committed the row, which the
	// write observer is told — the flush that ships it may run for someone
	// else (ADR-0295 §SD7).
	ident callident.CallIdentity
}

// endSection closes one section's frame. The buffer calls it once per
// section, after every component that contributed to it has written.
func (inst *TrailEntityBuilder) endSection(section string) error {
	switch section {
	case "symbol":
		inst.store.dml.GetSectionSymbol().EndSection()
	case "u64Array":
		inst.store.dml.GetSectionU64Array().EndSection()
	case "stringArray":
		inst.store.dml.GetSectionStringArray().EndSection()
	case "u32Array":
		inst.store.dml.GetSectionU32Array().EndSection()
	case "bool":
		inst.store.dml.GetSectionBool().EndSection()
	case "symbolArray":
		inst.store.dml.GetSectionSymbolArray().EndSection()
	case "textArray":
		inst.store.dml.GetSectionTextArray().EndSection()
	case "i64Array":
		inst.store.dml.GetSectionI64Array().EndSection()
	}
	return nil
}

// Begin opens one entity with the envelope roles as typed arguments
// (Key, Order) and the pass-through envelope, under context.Background(): a configured stamper
// that reads a call identity off the context finds none. See BeginCtx.
func (inst *TrailStore) Begin(id uint64, ts time.Time, env TrailEnvelope) *TrailEntityBuilder {
	return inst.BeginCtx(context.Background(), id, ts, env)
}

// BeginCtx is Begin with the context the configured stampers consult
// (ADR-0295 §SD7) — where a call identity reaches an actor stamper. The
// store stays single-goroutine; ctx is read during this call only.
func (inst *TrailStore) BeginCtx(ctx context.Context, id uint64, ts time.Time, env TrailEnvelope) *TrailEntityBuilder {
	lowlevel.InEntityFactsTableBeginEntity(inst.dml)
	lowlevel.InEntityFactsTableSetId(inst.dml, id, env.NaturalKey)
	lowlevel.InEntityFactsTableSetTimestamp(inst.dml, ts)
	lowlevel.InEntityFactsTableSetLifecycle(inst.dml, env.ExpiresAt)
	b := &TrailEntityBuilder{store: inst, key: id, ent: TrailEntity{ID: id, Ts: ts, TrailEnvelope: env}}
	b.ident, _ = callident.CallIdentityFrom(ctx)
	b.pushed = inst.applyStampers(ctx)
	return b
}

// AddOrigin contributes the Origin component to the open entity.
//
// The attributes are buffered, not written: a section frame closes for
// good, so a component that closed its own sections would shut out the
// next component sharing one. Commit writes them, one frame per section
// in first-seen order (ADR-0183 D4).
//
// A second Add of this component, or an Add on an entity already using
// Raw(), is refused: both used to mark the row un-mirrorable and carry
// on, which made its read-back shape depend on a call the writer had
// probably made by accident.
func (inst *TrailEntityBuilder) AddOrigin(row Origin) *TrailEntityBuilder {
	if err := inst.buf.StartKind("Origin"); err != nil {
		inst.store.dml.AppendError(err)
		return inst
	}
	inst.buf.Enqueue("symbol", "Origin", func() error {
		return originEmitSectionSymbol(inst.store.dml.GetSectionSymbol(), row)
	})
	inst.buf.Enqueue("u64Array", "Origin", func() error {
		return originEmitSectionU64Array(inst.store.dml.GetSectionU64Array(), row)
	})
	inst.ent.Origin = option.Some(row)
	return inst
}

